import { Roles } from '@/types/api.types';
import { GetUserRoles } from '@/utils/token';

/** Mirrors Policies.Admin on the API — advanced search is Admin / SuperAdmin only. */
export const canUseAdvancedSearch = (): boolean => {
    const roles = GetUserRoles();
    return roles.includes(Roles.Admin) || roles.includes(Roles.SuperAdmin);
};
